if (!process.env.STRAPI_URL) {
  throw new Error("STRAPI_URL is missing from .env.local");
}
if (!process.env.STRAPI_API_TOKEN) {
  throw new Error("STRAPI_API_TOKEN is missing from .env.local");
}

export const STRAPI_URL = process.env.STRAPI_URL;

export interface StrapiEntry<T> {
  id: number;
  attributes: T;
  meta?: Record<string, unknown>;
}

export interface StrapiResponse<T> {
  data: StrapiEntry<T>;
  meta: Record<string, unknown>;
}

export interface StrapiListResponse<T> {
  data: StrapiEntry<T>[];
  meta: {
    pagination: {
      page: number;
      pageSize: number;
      pageCount: number;
      total: number;
    };
  };
}

export async function strapiRequest<T>(
  method: "GET" | "POST" | "PUT" | "DELETE",
  path: string,
  body?: Record<string, unknown>,
): Promise<T> {
  const response = await fetch(`${STRAPI_URL}${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${process.env.STRAPI_API_TOKEN}`,
      "Content-Type": "application/json",
    },
    body: body ? JSON.stringify(body) : undefined,
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    const message =
      (error as { error?: { message?: string } }).error?.message ??
      `Strapi API error: ${response.status}`;
    throw new Error(message);
  }

  return response.json() as Promise<T>;
}

