"use server";

import { strapiRequest } from "./client";
import type { StrapiResponse, StrapiListResponse, StrapiEntry } from "./client";

export type { StrapiEntry, StrapiResponse, StrapiListResponse };

/**
 * Fetch all entries for a content type.
 * `contentType` is the plural API ID shown in Strapi's Content-Type Builder (e.g. "articles").
 * `populate=*` is included by default — override via `params` if needed.
 */
export async function findMany<T>(
  contentType: string,
  params?: Record<string, string>,
): Promise<StrapiEntry<T>[]> {
  const qs = new URLSearchParams({ populate: "*", ...params }).toString();
  const data = await strapiRequest<StrapiListResponse<T>>(
    "GET",
    `/api/${contentType}?${qs}`,
  );
  return data.data;
}

/** Fetch a single entry by numeric ID. */
export async function findOne<T>(
  contentType: string,
  id: number | string,
  params?: Record<string, string>,
): Promise<StrapiEntry<T>> {
  const qs = new URLSearchParams({ populate: "*", ...params }).toString();
  const data = await strapiRequest<StrapiResponse<T>>(
    "GET",
    `/api/${contentType}/${id}?${qs}`,
  );
  return data.data;
}

/**
 * Find entries where `slug` equals the given value.
 * Assumes your content type has a `slug` field.
 * Returns the first match or null.
 */
export async function findBySlug<T>(
  contentType: string,
  slug: string,
): Promise<StrapiEntry<T> | null> {
  const qs = new URLSearchParams({
    "filters[slug][$eq]": slug,
    populate: "*",
  }).toString();
  const data = await strapiRequest<StrapiListResponse<T>>(
    "GET",
    `/api/${contentType}?${qs}`,
  );
  return data.data[0] ?? null;
}

/** Create a new entry. `data` is the attributes object (not wrapped in `{ data: ... }`). */
export async function create<T>(
  contentType: string,
  data: Record<string, unknown>,
): Promise<StrapiEntry<T>> {
  const result = await strapiRequest<StrapiResponse<T>>(
    "POST",
    `/api/${contentType}`,
    { data },
  );
  return result.data;
}

/** Update an entry by ID. `data` is the partial attributes to update. */
export async function update<T>(
  contentType: string,
  id: number | string,
  data: Record<string, unknown>,
): Promise<StrapiEntry<T>> {
  const result = await strapiRequest<StrapiResponse<T>>(
    "PUT",
    `/api/${contentType}/${id}`,
    { data },
  );
  return result.data;
}

/** Delete an entry by ID. */
export async function deleteEntry(
  contentType: string,
  id: number | string,
): Promise<void> {
  await strapiRequest<unknown>("DELETE", `/api/${contentType}/${id}`);
}

