import crypto from "crypto";
import { revalidateTag, revalidatePath } from "next/cache";

export interface StrapiWebhookEvent {
  event:
    | "entry.create"
    | "entry.update"
    | "entry.delete"
    | "entry.publish"
    | "entry.unpublish"
    | "media.create"
    | "media.update"
    | "media.delete";
  createdAt: string;
  /** Content type name, e.g. "article", "product" */
  model: string;
  /** Full UID, e.g. "api::article.article" */
  uid: string;
  entry: Record<string, unknown>;
}

/**
 * Strapi sends the webhook secret verbatim as the `Authorization` header value.
 * Timing-safe comparison prevents oracle attacks on the string compare.
 */
export function verifyWebhookSecret(
  authHeader: string,
  secret: string,
): boolean {
  const a = Buffer.from(authHeader, "utf8");
  const b = Buffer.from(secret, "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

export async function handleStrapiEvent(
  event: StrapiWebhookEvent,
): Promise<void> {
  switch (event.event) {
    case "entry.publish":
    case "entry.unpublish": {
      // Invalidate the cache tag for this content type so the next request
      // re-fetches from Strapi. Tag your fetch calls with the model name:
      //   fetch(url, { next: { tags: [event.model] } })
      revalidateTag(event.model);
      // TODO: Narrow this to specific paths if you don't want a full-site
      // revalidation — e.g. revalidatePath(`/${event.model}`) or per-slug.
      revalidatePath("/", "layout");
      console.log(
        `[strapi] Revalidated tag "${event.model}" and path "/" on ${event.event}`,
      );
      break;
    }
    case "entry.create":
    case "entry.update":
    case "entry.delete": {
      revalidateTag(event.model);
      console.log(
        `[strapi] Revalidated tag "${event.model}" on ${event.event}`,
      );
      break;
    }
    case "media.create":
    case "media.update":
    case "media.delete": {
      revalidateTag("media");
      console.log(`[strapi] Revalidated tag "media" on ${event.event}`);
      break;
    }
    default:
      console.log(`[strapi] Unhandled event: ${event.event}`);
  }
}

