import { headers } from "next/headers";
import {
  handleStrapiEvent,
  verifyWebhookSecret,
} from "@/infra/strapi/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const authHeader = headersList.get("Authorization");

  if (!authHeader) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.STRAPI_WEBHOOK_SECRET) {
    console.error("[strapi webhook] STRAPI_WEBHOOK_SECRET is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (!verifyWebhookSecret(authHeader, process.env.STRAPI_WEBHOOK_SECRET)) {
    console.error("[strapi webhook] Invalid Authorization header");
    return new Response("Unauthorized", { status: 401 });
  }

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  let event;
  try {
    event = JSON.parse(body);
  } catch (err: unknown) {
    console.error("[strapi webhook] Malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so Strapi retries — distinct from 4xx above.
  try {
    await handleStrapiEvent(event);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[strapi webhook] Handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}
